return {["fb40_01"]={["dsc"]=[[这是一个用木板和石头垒成的小庙，庙里有一尊残破的佛像，香灰撒得到处都是。]],["id"]=[[fb40_01]],["item1"]=[[fb40item48]],["leftDown"]=[[fb40_02]],["name"]=[[山神庙]],["permission"]=2,["role1"]=[[fb40r01_1]],["stepMusic"]=[[jiaobu]]},["fb40_02"]={["dsc"]=[[这是城东的一条荒路，路旁杂乱的长着齐膝的荒草，远近荒无一人。两旁干枯的老树上落满了成群的乌鸦，凄凉的鸣叫声在荒野上远远传去，一派凄凉的景象。]],["fightBackground"]=[[山内]],["id"]=[[fb40_02]],["leftDown"]=[[fb40_08]],["leftUp"]=[[fb40_49]],["name"]=[[荒路]],["permission"]=2,["rightUp"]=[[fb40_01]],["stepMusic"]=[[xuedi]]},["fb40_03"]={["down"]=[[fb40_10]],["dsc"]=[[这里是古镇船厂。船厂是位于关外大平原中部的一个古老的小镇，此镇西、南、北、三面是以高墙垒筑，利于坚守。东面临松花江天成天险，乃兵家必争的要地。松花江在冬春时结冰可通行，夏秋化冻你只好找船家帮忙了。]],["fightBackground"]=[[山内]],["id"]=[[fb40_03]],["item1"]=[[fb40item50]],["item2"]=[[fb40item52]],["item3"]=[[fb40item54]],["item4"]=[[fb40item66]],["name"]=[[船厂]],["permission"]=1,["right"]=[[fb40_04]],["role1"]=[[fb40r03_1]],["stepMusic"]=[[xuedi]]},["fb40_04"]={["dsc"]=[[这里是松花江的江面，现已冻成了几尺厚的坚冰。行人或马匹，车辆均可横逾江面而绝无危险。冰面上留有厚厚的积雪，与两岸连成一片，只有中间经常行走之处，露出一条青色的冰路。]],["fightBackground"]=[[山内]],["id"]=[[fb40_04]],["item1"]=[[fb40item10]],["item2"]=[[fb40item67]],["left"]=[[fb40_03]],["name"]=[[冰面]],["permission"]=1,["right"]=[[fb40_05]],["stepMusic"]=[[xuedi]]},["fb40_05"]={["dsc"]=[[这里是沿江向东的古道，多为进山采参的参客所走，因此也称“参路”。前面一座小山截断去路，因其型似门坎，且为东去采参的第一道屏障，故被称为大门坎子。西面是宽阔的松花江。松花江在冬春时结冰可通行，夏秋化冻你只好找船家帮忙了。]],["fightBackground"]=[[山内]],["id"]=[[fb40_05]],["left"]=[[fb40_04]],["name"]=[[大门坎子]],["permission"]=1,["rightDown"]=[[fb40_11]],["stepMusic"]=[[xuedi]]},["fb40_06"]={["dsc"]=[[这是一个僻静幽深的小巷，四周寂静无声，一个人影也没有。长长的石板路上落了一层厚厚的积雪，踩在脚下发出“咯吱”的响声。小巷的尽头有一座土屋。]],["fightBackground"]=[[山内]],["id"]=[[fb40_06]],["leftDown"]=[[fb40_13]],["name"]=[[小巷]],["permission"]=2,["right"]=[[fb40_07]],["stepMusic"]=[[xuedi]]},["fb40_07"]={["down"]=[[fb40_14]],["dsc"]=[[这里是用黄土铺就的街道，街上的行人不多，看起来很冷清。街上有些乞丐在向你乞讨。偶尔有几个身着异域服饰的行人走过，西面有一条幽深的小巷，不知通向何处。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb40_07]],["item1"]=[[fb40item49]],["item2"]=[[cgbftrigger05]],["left"]=[[fb40_06]],["name"]=[[北城]],["permission"]=2,["role1"]=[[fb40r07_2]],["stepMusic"]=[[xuedi]],["up"]=[[fb40_50]]},["fb40_08"]={["down"]=[[fb40_15]],["dsc"]=[[这是城东的一条荒路，路旁杂乱的长着齐膝的荒草，远近荒无一人。两旁干枯的老树上落满了成群的乌鸦，凄凉的鸣叫声在荒野上远远传去，一派凄凉的景象。]],["fightBackground"]=[[山内]],["id"]=[[fb40_08]],["name"]=[[荒路]],["permission"]=2,["rightUp"]=[[fb40_02]],["stepMusic"]=[[xuedi]]},["fb40_09"]={["dsc"]=[[这里是一片白茫茫的雪地，一眼望不到边际。四周一个人影也没有，厚厚的积雪踩起来发出咯吱的响声，大地上留下一串孤独的脚印。寒冷的北风呼啸而过，吹得脸生痛。暗淡的太阳低悬在天边，显得那么苍白。]],["fightBackground"]=[[山内]],["id"]=[[fb40_09]],["item1"]=[[fb40item65]],["leftDown"]=[[fb40_16]],["name"]=[[雪地]],["permission"]=1,["right"]=[[fb40_10]],["stepMusic"]=[[xuedi]]},["fb40_10"]={["dsc"]=[[这里是一片白茫茫的雪地，一眼望不到边际。四周一个人影也没有，厚厚的积雪踩起来发出咯吱的响声，大地上留下一串孤独的脚印。寒冷的北风呼啸而过，吹得脸生痛。暗淡的太阳低悬在天边，显得那么苍白。]],["fightBackground"]=[[山内]],["id"]=[[fb40_10]],["left"]=[[fb40_09]],["name"]=[[雪地]],["permission"]=1,["role1"]=[[fb40r10_1]],["role2"]=[[fb40r10_2]],["stepMusic"]=[[xuedi]],["up"]=[[fb40_03]]},["fb40_11"]={["dsc"]=[[漫长的参路蜿蜒地消失在原处的天边，路上依稀还留有一些浅浅的足印，看来是前面的参客留下的。白茫茫的雪地反射出耀眼的银光，看得人头昏眼花。偶尔有几只雪兔飞驰而过，转眼就无影无踪了。]],["fightBackground"]=[[山内]],["id"]=[[fb40_11]],["item1"]=[[fb40item11]],["leftUp"]=[[fb40_05]],["name"]=[[二门坎子]],["permission"]=1,["right"]=[[fb40_12]],["stepMusic"]=[[xuedi]]},["fb40_12"]={["dsc"]=[[这里是一片开阔的平原，附近不但没有任何小山丘陵，就连一棵树也找不到。抬眼望去，地平线笔直的将蓝天与雪原分隔在两边。据说夜间因这里无物遮挡，可遍观满天星斗。进山的人们多在此祈求上苍的保佑。]],["fightBackground"]=[[山内]],["id"]=[[fb40_12]],["left"]=[[fb40_11]],["name"]=[[满天星]],["permission"]=1,["rightDown"]=[[fb40_17]],["stepMusic"]=[[xuedi]]},["fb40_13"]={["dsc"]=[[这是一座用黄土垒成的小屋，屋内打扫的很干净。四周的墙壁上挂满了各种棍子，钎子，开山斧，小锯子等工具。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb40_13]],["item1"]=[[fb40item63]],["name"]=[[小土屋]],["permission"]=2,["rightUp"]=[[fb40_06]],["role1"]=[[fb40r13_1]],["roomBgm"]=[[chengzhenbaitian]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]]},["fb40_14"]={["down"]=[[fb40_24]],["dsc"]=[[这里是城中一片开阔的广场，乃是来往客商交易毛皮，药材以及其它杂物的集市。由于附近方圆百里仅有这么一个集市，因此这里的人最多，货物也最全。不同的服饰，不同的语言都可以在这里看到，听到。杂乱的人群中传出各种吆喝，叫卖的声音。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb40_14]],["name"]=[[集市]],["permission"]=1,["right"]=[[fb40_15]],["role1"]=[[fb40r14_1]],["role2"]=[[fb40r14_2]],["role3"]=[[fb40r14_3]],["roomBgm"]=[[chengzhenbaitian]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]],["up"]=[[fb40_07]]},["fb40_15"]={["down"]=[[fb40_25]],["dsc"]=[[这里是用黄土铺就的街道，街上的行人不多，看起来很冷清。偶尔有几个身着异域服饰的行人走过，西面传来零星的的叫卖声。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb40_15]],["left"]=[[fb40_14]],["name"]=[[东城]],["permission"]=1,["right"]=[[fb40_16]],["role1"]=[[fb40r15_1c]],["role2"]=[[fb40r15_2]],["role3"]=[[fb40r15_3]],["roomBgm"]=[[chengzhenbaitian]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[xuedi]],["up"]=[[fb40_08]]},["fb40_16"]={["dsc"]=[[这里是一片白茫茫的雪地，一眼望不到边际。四周一个人影也没有，厚厚的积雪踩起来发出咯吱的响声，大地上留下一串孤独的脚印。寒冷的北风呼啸而过，吹得脸生痛。暗淡的太阳低悬在天边，显得那么苍白。]],["fightBackground"]=[[山内]],["id"]=[[fb40_16]],["left"]=[[fb40_15]],["name"]=[[雪地]],["permission"]=1,["rightUp"]=[[fb40_09]],["role1"]=[[fb40r16_1]],["stepMusic"]=[[xuedi]]},["fb40_17"]={["dsc"]=[[经过一番艰苦的跋涉，你的眼前出现了一片低矮的丘陵。远远看去像秋收后堆成的谷草垛，密密麻麻，数不清有多少个。翻过这片丘陵再向东行，就可进入长白大山了。东面的天边有一缕炊烟，看来似乎有人。]],["fightBackground"]=[[山内]],["id"]=[[fb40_17]],["item1"]=[[fb40item12]],["leftUp"]=[[fb40_12]],["name"]=[[谷草垛]],["permission"]=1,["right"]=[[fb40_18]],["role1"]=[[fb40r17_1]],["stepMusic"]=[[xuedi]]},["fb40_18"]={["dsc"]=[[这里是长白山下的一个小村，只有四，五间粗陋的小木屋。这里并没有固定的居民，木屋都是进山采参的参客所盖，为的是在进山前能在这里好好的休息一下。东面就是巍峨耸立的长白大山。]],["fightBackground"]=[[山内]],["id"]=[[fb40_18]],["item1"]=[[fb40item37]],["left"]=[[fb40_17]],["name"]=[[白河]],["permission"]=1,["right"]=[[fb40_19]],["stepMusic"]=[[xuedi]]},["fb40_19"]={["dsc"]=[[这是一片茂密的松林，杂乱的生长在倾斜的山坡上。每棵松树都有三四抱粗细，高达十几丈。树冠枝多叶密，将天空完全遮住，因此林内显得有些昏暗。树木之间长着很多灌木杂草，使行走很艰难，据说人参就生长在这些杂草之中。]],["fightBackground"]=[[山内]],["id"]=[[fb40_19]],["left"]=[[fb40_18]],["name"]=[[密林]],["permission"]=1,["right"]=[[fb40_20]],["role1"]=[[fb40r19_1]],["stepMusic"]=[[xuedi]]},["fb40_20"]={["dsc"]=[[这里是密林中的险恶之境周围是为茂密的松林，不见天光。林中传来野兽饥饿之极的嘶吼。四处有不知名的草菰和野果，可你一点也不敢尝尝。林木幽暗深邃，似乎暗藏杀机。你到了此处，心胆俱裂，只想快点离开。]],["fightBackground"]=[[山内]],["id"]=[[fb40_20]],["left"]=[[fb40_19]],["name"]=[[黑风口]],["permission"]=1,["right"]=[[fb40_21]],["stepMusic"]=[[xuedi]]},["fb40_21"]={["dsc"]=[[小天池又称长白镜湖，圆圆如镜。湖水碧蓝，林海峭壁倒映其间，风光幽丽，一层绿里透红的细沙，均匀地铺在湖底，恰似展开着的一幅金丝绒毯。相传天上仙女每日天池中沐浴，洗毕就到天豁峰的峰巅，坐在两个峰尖中间的开阔岩石上，对着小天池打扮梳妆，故名镜湖。]],["fightBackground"]=[[山内]],["id"]=[[fb40_21]],["item1"]=[[fb40item13]],["item2"]=[[fb40item68]],["left"]=[[fb40_20]],["name"]=[[小天池]],["permission"]=1,["right"]=[[fb40_22]],["stepMusic"]=[[xuedi]]},["fb40_22"]={["dsc"]=[[天池水从两百余尺高飞流跌落，轰鸣之声远传数里，水花直落大嶂谷，与天然屏障玉壁、金壁相映，恰似白练当空，水柱扑向深深的谷底，溅起几丈高的飞浪，犹如仙女散花，阳光照射下，虹飞氤跃，璀灿壮观之极。古人诗云:“白河两岸景清幽，碧水悬崖万古留。疑似龙池喷瑞雪，如同天际挂飞流。不须鞭石渡沧海，直可乘槎问斗牛？欲识林泉真乐趣，明朝结伴再来游。”]],["fightBackground"]=[[山内]],["id"]=[[fb40_22]],["left"]=[[fb40_21]],["name"]=[[长白瀑布]],["permission"]=1,["rightDown"]=[[fb40_26]],["role1"]=[[fb40r22_1]],["stepMusic"]=[[xuedi]]},["fb40_23"]={["dsc"]=[[这是一间很小的狗肉馆，不过已经被废弃。屋内有一个很大的土炕，几乎占去了房间的一半。炕中是一个火灶，上架一口大铁锅，铁锅已经锈穿。地上铺满杂草，窗户到处破着洞，凛冽的风灌了进来。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb40_23]],["name"]=[[香肉馆]],["permission"]=2,["right"]=[[fb40_24]],["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["roomBgm"]=[[chengzhenbaitian]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]]},["fb40_24"]={["down"]=[[fb40_27]],["dsc"]=[[这里是用黄土铺就的街道，街上的行人不多，看起来很冷清。偶尔有几个身着异域服饰的行人走过。西面有一座低矮的土房，看起来像一个小饭馆，但好像已经废弃。]],["fightBackground"]=[[村庄室外]],["id"]=[[fb40_24]],["item1"]=[[fb40item74]],["left"]=[[fb40_23]],["name"]=[[南城]],["permission"]=1,["role1"]=[[fb40r24_1]],["roomBgm"]=[[chengzhenbaitian]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]],["up"]=[[fb40_14]]},["fb40_25"]={["dsc"]=[[这里是平王部队集结的地方，被守卫围成了铁桶，想要进入的人都被严厉的盘查着。守卫都透着一股森然的寒意，想要擅闯的人恐怕都成了刀下鬼。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb40_25]],["name"]=[[军营]],["permission"]=1,["role1"]=[[fb40r25_1]],["role2"]=[[fb40r25_2]],["roomBgm"]=[[chengzhenbaitian]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]],["up"]=[[fb40_15]]},["fb40_26"]={["dsc"]=[[天池三面壅注不流，惟独北面偏东一线斜垂，白练飞舞，这就是达门。池水经达门外流，水流清冷，在石壁间冲撞有声。]],["fightBackground"]=[[山内]],["id"]=[[fb40_26]],["leftDown"]=[[fb40_29]],["leftUp"]=[[fb40_22]],["name"]=[[达门]],["permission"]=1,["stepMusic"]=[[xuedi]]},["fb40_27"]={["down"]=[[fb40_31]],["dsc"]=[[这是一座年久失修的破木桥，由几根树干捆扎而成。下面的河水早以结成坚冰。]],["fightBackground"]=[[山内]],["id"]=[[fb40_27]],["item1"]=[[cgbftrigger04]],["name"]=[[木桥]],["permission"]=2,["role1"]=[[fb40r27_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb40_24]]},["fb40_28"]={["down"]=[[fb40_33]],["dsc"]=[[龙门峰西侧就是鹿鸣峰。鹿鸣峰又称芝盘峰，因峰上有一草甸子，形圆如盖，有热气从地下冒出，每到严冬，其它峰均积雪甚厚，唯鹿鸣峰依然植物茂盛，且盛产芝草，鹿多居之。常有鹤、雀、雕、燕飞落其上，有“鹿鸣翠谷，雕飞芝盖”之称。]],["fightBackground"]=[[山内]],["id"]=[[fb40_28]],["name"]=[[鹿鸣峰]],["permission"]=2,["right"]=[[fb40_29]],["role1"]=[[fb40r28_1]],["stepMusic"]=[[xuedi]]},["fb40_29"]={["down"]=[[fb40_34]],["dsc"]=[[龙门峰在乘槎河西岸，因状如门形，故名龙门。崇崖峻壁，形态奇特，宛如卧龙吸水，传说大禹治水曾到此峰，旁有蝌蚪形石柱。]],["fightBackground"]=[[山内]],["id"]=[[fb40_29]],["item1"]=[[fb40item38]],["left"]=[[fb40_28]],["name"]=[[龙门峰]],["permission"]=1,["right"]=[[fb40_30]],["rightUp"]=[[fb40_26]],["stepMusic"]=[[xuedi]]},["fb40_30"]={["down"]=[[fb40_35]],["dsc"]=[[乘槎河东岸，与龙门峰对峙。峰顶如鹰嘴般的峻峭山峰破石而出，伸向天池，故又名鹰嘴峰。古书载：“峰起双尖，中辟一线，有豁然开朗、令人不可思议之趣”，相传为大禹治水所劈，石多赤色，犹如二龙蟠踞，妙趣横生。]],["fightBackground"]=[[山内]],["id"]=[[fb40_30]],["left"]=[[fb40_29]],["name"]=[[天豁峰]],["permission"]=2,["stepMusic"]=[[xuedi]]},["fb40_31"]={["down"]=[[fb40_36]],["dsc"]=[[这里是通往关外的官道，几米宽的大道，全部由黄土铺成，可并行三四辆马车而不显拥挤。这里是进出关口的必经之路，路上三两成群的行人都是往来贩运皮货，药材的生意人。偶尔有官兵骑马飞驰而过。]],["fightBackground"]=[[山内]],["id"]=[[fb40_31]],["item1"]=[[cgbftrigger03]],["name"]=[[大道]],["permission"]=2,["stepMusic"]=[[xuedi]],["up"]=[[fb40_27]]},["fb40_32"]={["down"]=[[fb40_37]],["dsc"]=[[玉柱峰北，有一山峰，峰脊出梯河瀑布，远望如腾白如云，纵列如梯，故名梯云峰。]],["fightBackground"]=[[山内]],["id"]=[[fb40_32]],["item1"]=[[fb40r32_5]],["item2"]=[[fb40r32_6]],["name"]=[[梯云峰]],["permission"]=2,["role1"]=[[fb40r32_1]],["role2"]=[[fb40r32_2]],["role3"]=[[fb40r32_3]],["role4"]=[[fb40r32_4]],["stepMusic"]=[[xuedi]]},["fb40_33"]={["dsc"]=[[白云峰在天池之西，鹿鸣峰之南，为长白山主峰。山峰圆而高大，临天池而耸立，巍峨磅礴，如一口宝剑直插云天。天气晴好，天池十六峰毕露，惟独此峰常有烟云缭绕，终日不散。古人有“看罢归来回首顾，白山依旧白云封”的赞语。登临此峰，诚有飘飘欲仙之感。]],["fightBackground"]=[[山内]],["id"]=[[fb40_33]],["item1"]=[[fb40item59]],["item2"]=[[fb40item60]],["leftDown"]=[[fb40_37]],["name"]=[[白云峰]],["permission"]=2,["right"]=[[fb40_34]],["role1"]=[[fb40r33_1]],["stepMusic"]=[[xuedi]],["up"]=[[fb40_28]]},["fb40_34"]={["down"]=[[fb40_38]],["dsc"]=[[天池十天九雾，云蒸雾绕，变幻无穷。瞬息万变的雾霭风雨，使天池时而清亮如蓝天明镜，时而缥缈如轻莹薄纱，时而腾跃如大海波涛，景色大观令人神往。]],["fightBackground"]=[[山内]],["id"]=[[fb40_34]],["left"]=[[fb40_33]],["name"]=[[长白天池]],["permission"]=1,["right"]=[[fb40_35]],["stepMusic"]=[[xuedi]],["up"]=[[fb40_29]]},["fb40_35"]={["dsc"]=[[长白东侧最高峰，自古以来，华盖峰就是风雨云雾的故道。云雾起处，恰似掀开锅盖一般，雾气翻滚，池水云天，一脉相连，气壮华夏，故名华盖峰。]],["fightBackground"]=[[山内]],["id"]=[[fb40_35]],["item1"]=[[fb40item42]],["left"]=[[fb40_34]],["name"]=[[华盖峰]],["permission"]=2,["role1"]=[[fb40r35_1]],["stepMusic"]=[[xuedi]],["up"]=[[fb40_30]]},["fb40_36"]={["dsc"]=[[这里是关外驻防的军事重镇。城高河宽，守备森严，城楼上不但有大量的官兵驻防，甚至还有几门红衣火炮，架设其上。城门旁几名官兵正在检察来往行人的物品，不时传来几声叱骂之声。]],["fightBackground"]=[[山内]],["id"]=[[fb40_36]],["item1"]=[[cgbftrigger02]],["leftDown"]=[[fb40_39]],["name"]=[[宁远]],["permission"]=2,["stepMusic"]=[[xuedi]],["up"]=[[fb40_31]]},["fb40_37"]={["dsc"]=[[白云峰西南，有峰高耸挺秀，多峰突起，形如玉柱。东麓泻出一水，悬流如线，注入天池，就是古籍所载的“金线泉”了。]],["fightBackground"]=[[山内]],["id"]=[[fb40_37]],["item1"]=[[fb40item60]],["item2"]=[[fb40item60]],["item3"]=[[fb40item69]],["name"]=[[玉柱峰]],["permission"]=2,["rightUp"]=[[fb40_33]],["stepMusic"]=[[xuedi]],["up"]=[[fb40_32]]},["fb40_38"]={["dsc"]=[[天池在长白山巅中心点，群峰环抱，离地高约二十里，故名天池。天池碧波盈盈，清澈湛蓝。湖周围峭壁百丈，峰影云影倒映其中，湖光山色、岚影云天十分诱人。湖岸周遭芳草茵茵，百花吐艳。]],["fightBackground"]=[[山内]],["id"]=[[fb40_38]],["item1"]=[[fb40item14]],["item2"]=[[fb40item77]],["name"]=[[长白天池]],["permission"]=1,["stepMusic"]=[[xuedi]],["up"]=[[fb40_34]]},["fb40_39"]={["dsc"]=[[这里是通往关外的官道，几米宽的大道，全部由黄土铺成，可并行三四辆马车而不显拥挤。这里是进出关口的必经之路，路上三俩成群的行人都是往来贩运皮货，药材的生意人。偶尔有身着官兵骑马飞驰而过。]],["fightBackground"]=[[山内]],["id"]=[[fb40_39]],["leftDown"]=[[fb40_40]],["name"]=[[官道]],["permission"]=2,["rightUp"]=[[fb40_36]],["role1"]=[[fb40r39_1]],["role2"]=[[fb40r39_2]],["role3"]=[[fb40r39_3]],["stepMusic"]=[[xuedi]]},["fb40_40"]={["dsc"]=[[这里就是长城最东面的重要关口：山海关。这里地势险要，自古就是关外通往中原的必经之地。站在关楼上北望，角山，古堡，烽火台历历在目，南沿长城远眺，直深入海的老龙头依稀可见。城楼二楼上悬挂着一块巨幅横匾。]],["fightBackground"]=[[山内]],["id"]=[[fb40_40]],["item1"]=[[fb40item62]],["item2"]=[[cgbftrigger01]],["name"]=[[山海关]],["permission"]=2,["rightDown"]=[[fb40_41]],["rightUp"]=[[fb40_39]],["stepMusic"]=[[xuedi]]},["fb40_41"]={["dsc"]=[[老龙头是长城最东端。澄海楼巍峨高踞城头，楼上“雄襟万里”的横匾居高临下，直俯大海。自澄海楼筑有一石城逐级而下伸入大海，站在石城终端楼平台上四眺，海天一色，无边无际，气象万千。]],["fightBackground"]=[[山内]],["id"]=[[fb40_41]],["item1"]=[[fb40item75]],["leftUp"]=[[fb40_40]],["name"]=[[老龙头]],["permission"]=2,["stepMusic"]=[[xuedi]]},["fb40_42"]={["down"]=[[fb40_46]],["dsc"]=[[这是陪葬的墓室，摆着十三具木质的棺材，棺材上落着很厚的灰。]],["id"]=[[fb40_42]],["item1"]=[[fb40item41]],["item2"]=[[fb40item32]],["name"]=[[耳室]],["permission"]=1,["roomBgm"]=[[mengjing]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]]},["fb40_43"]={["dsc"]=[[这座墓门全部是汉白玉完整雕刻而成，左龙右凤，雕工十分了得，价值连城。]],["id"]=[[fb40_43]],["item1"]=[[fb40item27]],["item2"]=[[fb40item16]],["name"]=[[墓门]],["permission"]=1,["right"]=[[fb40_44]],["roomBgm"]=[[mengjing]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]]},["fb40_44"]={["dsc"]=[[这条通道没有光线，两边摆设的长明灯早已熄灭，青石板的地面踩上去整条通道都是回声，令人不禁神经紧绷。]],["id"]=[[fb40_44]],["item1"]=[[fb40item41]],["item2"]=[[fb40item28]],["left"]=[[fb40_43]],["name"]=[[甬道]],["permission"]=1,["right"]=[[fb40_45]],["roomBgm"]=[[mengjing]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]]},["fb40_45"]={["dsc"]=[[这条通道没有光线，两边摆设的长明灯早已熄灭，青石板的地面踩上去整条通道都是回声，令人不禁神经紧绷。]],["id"]=[[fb40_45]],["item1"]=[[fb40item41]],["item2"]=[[fb40item29]],["left"]=[[fb40_44]],["name"]=[[甬道]],["permission"]=1,["right"]=[[fb40_46]],["roomBgm"]=[[mengjing]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]]},["fb40_46"]={["down"]=[[fb40_47]],["dsc"]=[[这个宽敞的地方便是主墓室了。正中间摆放着巨大的纯金镂空棺椁，棺椁周围挖开了水池，似乎深不见底。四周摆放着大大小小的锦盒，应该是陪葬品。]],["id"]=[[fb40_46]],["item1"]=[[fb40item76]],["item2"]=[[fb40item18]],["item3"]=[[fb40item19]],["item4"]=[[fb40item20]],["item5"]=[[fb40item21]],["left"]=[[fb40_45]],["name"]=[[主墓室]],["permission"]=1,["roomBgm"]=[[mengjing]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]],["up"]=[[fb40_42]]},["fb40_47"]={["dsc"]=[[这是放陪葬品的墓室，里面摆着各种生活器具，保存完好。]],["id"]=[[fb40_47]],["item1"]=[[fb40item41]],["item2"]=[[fb40item31]],["name"]=[[耳室]],["permission"]=1,["roomBgm"]=[[mengjing]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]],["up"]=[[fb40_46]]},["fb40_48"]={["dsc"]=[[华盖峰往下眺望，就是谷底了。这里气候温暖，并无白雪覆盖。一条小溪蜿蜒流过。四周有很多鹿，四处嬉戏着，见你靠近都没有跑开。]],["fightBackground"]=[[山内]],["id"]=[[fb40_48]],["item1"]=[[fb40item45]],["name"]=[[谷底]],["permission"]=2,["role1"]=[[fb40r48_1]],["stepMusic"]=[[xuedi]]},["fb40_49"]={["dsc"]=[[荒路的尽头有一座观音庙，抬眼望去，整个木结构的观音庙到处是孔洞，如风烛残年的老人在风中叹息着。庙门早已烂的没了踪影，进入观音庙，香炉、桌子胡乱堆着，到处结着蛛网。地上铺满一捏就碎的稻草，上面裹满了灰尘。正中有一尊观音像，只是外漆早已剥落，显得破败不堪。]],["id"]=[[fb40_49]],["name"]=[[观音庙]],["permission"]=2,["rightDown"]=[[fb40_02]],["role1"]=[[fb40r49_1]],["roomBgm"]=[[chengzhenbaitian]],["roomBgmRule"]=1,["spaceTime"]=0,["stepMusic"]=[[jiaobu]]},["fb40_50"]={["down"]=[[fb40_07]],["dsc"]=[[这是城北的一条荒路，路旁杂乱的长着齐膝的荒草，远近荒无一人。两旁干枯的老树上落满了成群的乌鸦，凄凉的鸣叫声在荒野上远远传去，一派凄凉的景象。]],["fightBackground"]=[[山内]],["id"]=[[fb40_50]],["name"]=[[荒路]],["permission"]=2,["role1"]=[[fb40r50_1]],["role2"]=[[fb40r50_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb40_51]]},["fb40_51"]={["down"]=[[fb40_50]],["dsc"]=[[北城出城外是一条荒路，直通向一个强盗聚集的山寨，眼前是一座山寨大门，木制的栅栏围着山寨，左右各一座哨塔，上面有强盗打扮的人左右观望。哨塔前燃着篝火。]],["id"]=[[fb40_51]],["name"]=[[山寨大门]],["permission"]=2,["role1"]=[[fb40r51_1]],["role2"]=[[fb40r51_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb40_52]]},["fb40_52"]={["down"]=[[fb40_51]],["dsc"]=[[进入山寨大门便是强盗的聚集地了。这里是土碉楼的建筑方法，一座座木楼层层叠进，将山寨正中的一座大宅团团围住。强盗们来来往往，有的酩酊大醉倒在路边，有的带着敌意看着你。]],["fightBackground"]=[[村庄室内]],["id"]=[[fb40_52]],["name"]=[[强盗山寨]],["permission"]=2,["role1"]=[[fb40r52_1]],["role2"]=[[fb40r52_2]],["stepMusic"]=[[jiaobu]]}}00000000